import 'package:flutter/material.dart';import '../../../services/auth/auth_service.dart';import '../../../services/personal_ai/future_simulator_service.dart';
class AurenFutureSimulatorScreen extends StatefulWidget{const AurenFutureSimulatorScreen({super.key});@override State<AurenFutureSimulatorScreen> createState()=>_AurenFutureSimulatorScreenState();}
class _AurenFutureSimulatorScreenState extends State<AurenFutureSimulatorScreen>{final auth=FirebaseAurenAuthService();final s=AurenFutureSimulatorService();final goal=TextEditingController(),state=TextEditingController(),options=TextEditingController();List<AurenFutureScenario> scenarios=[];@override void dispose(){goal.dispose();state.dispose();options.dispose();super.dispose();}void run(){final g=goal.text.trim();final os=options.text.split(',').map((x)=>x.trim()).where((x)=>x.isNotEmpty).toList();if(g.isEmpty||os.isEmpty)return;setState(()=>scenarios=s.simulate(goal:g,currentState:state.text.trim(),options:os));}Future<void> save()async{final uid=auth.currentUserId;if(uid!=null&&scenarios.isNotEmpty)await s.save(uid,scenarios);}@override Widget build(BuildContext context){if(auth.currentUserId==null)return const Scaffold(body:Center(child:Text('سجّل الدخول أولاً.')));return Scaffold(appBar:AppBar(title:const Text('Future Simulator')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('جرّب مسارات مختلفة للمستقبل. النتائج سيناريوهات للتخطيط وليست تنبؤات.'),const SizedBox(height:16),_f(goal,'الهدف'),_f(state,'الوضع الحالي'),_f(options,'المسارات — افصل بينها بفاصلة'),FilledButton(onPressed:run,child:const Text('شغّل المحاكاة')),if(scenarios.isNotEmpty)FilledButton.tonal(onPressed:save,child:const Text('حفظ السيناريوهات')), ...scenarios.map((x)=>Card(child:ExpansionTile(title:Text(x.title),subtitle:Text(x.horizon),children:[Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(x.description),const SizedBox(height:8),Text(x.assumptions),const SizedBox(height:8),...x.actions.map((a)=>Text('• '+a))]))])))]);}Widget _f(TextEditingController c,String l)=>Padding(padding:const EdgeInsets.only(bottom:10),child:TextField(controller:c,maxLines:l=='الوضع الحالي'?3:1,decoration:InputDecoration(labelText:l,border:const OutlineInputBorder())));}